using sv_a31ac4b23f6843529acdc18750567079.Client.Models;
using sv_a31ac4b23f6843529acdc18750567079.Client.Services;

namespace sv_a31ac4b23f6843529acdc18750567079.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTime(2026, 7, 2),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 20, 8, 0, 0), Description = "Package picked up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 21, 14, 30, 0), Description = "Arrived at sorting facility", Location = "Phoenix, AZ" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 23, 6, 15, 0), Description = "Departed facility", Location = "Memphis, TN" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTime(2026, 6, 22),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 18, 9, 0, 0), Description = "Package picked up", Location = "Chicago, IL" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 19, 16, 0, 0), Description = "In transit", Location = "Cleveland, OH" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 21, 10, 45, 0), Description = "Out for delivery", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 21, 14, 20, 0), Description = "Delivered — signed by J. Smith", Location = "New York, NY" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTime(2026, 7, 5),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 24, 20, 0, 0), Description = "Label created", Location = "Seattle, WA" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_a31ac4b23f6843529acdc18750567079.Client.Models
@using sv_a31ac4b23f6843529acdc18750567079.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (isLoading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <h1>Shipment @shipment.TrackingNumber</h1>

    <dl class="row">
        <dt class="col-sm-3">Status</dt>
        <dd class="col-sm-9">@shipment.Status</dd>

        <dt class="col-sm-3">Location</dt>
        <dd class="col-sm-9">@shipment.Location</dd>

        <dt class="col-sm-3">Estimated Delivery</dt>
        <dd class="col-sm-9">@(shipment.EstimatedDelivery?.ToString("MMMM d, yyyy") ?? "—")</dd>
    </dl>

    @if (shipment.StatusUpdates.Count > 0)
    {
        <h2>Tracking History</h2>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? shipment;
    private bool isLoading;
    private string? errorMessage;

    private CancellationTokenSource? cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request (handles navigating to a new tracking number)
        await CancelPendingRequestAsync();

        cts = new CancellationTokenSource();
        var ct = cts.Token;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled — nothing to show
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (HttpRequestException ex)
        {
            Logger.LogError(ex, "Network error loading shipment {TrackingNumber}", TrackingNumber);
            errorMessage = "A network error occurred. Please check your connection and try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Unexpected error loading shipment {TrackingNumber}", TrackingNumber);
            errorMessage = "Something went wrong. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    private async Task CancelPendingRequestAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
            cts = null;
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
        cts = null;
    }
}

